package com.arena.core.training;
import com.arena.core.exception.*;import org.junit.jupiter.api.*;import org.springframework.test.web.servlet.*;import org.springframework.security.oauth2.jwt.Jwt;import static org.mockito.Mockito.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
class StaffRegistrationApiTest {
 StaffRegistrationService service;MockMvc mvc;Jwt jwt;
 @BeforeEach void setup(){service=mock(StaffRegistrationService.class);jwt=Jwt.withTokenValue("owner").header("alg","none").subject("owner").build();mvc=org.springframework.test.web.servlet.setup.MockMvcBuilders.standaloneSetup(new StaffRegistrationController(service)).setControllerAdvice(new GlobalExceptionHandler()).setCustomArgumentResolvers(new org.springframework.web.method.support.HandlerMethodArgumentResolver(){public boolean supportsParameter(org.springframework.core.MethodParameter p){return p.getParameterType()==Jwt.class;}public Object resolveArgument(org.springframework.core.MethodParameter p,org.springframework.web.method.support.ModelAndViewContainer c,org.springframework.web.context.request.NativeWebRequest r,org.springframework.web.bind.support.WebDataBinderFactory b){return jwt;}}).build();}
 @Test void usernameAndEmailConflictsHaveSafeFieldSpecificResponses()throws Exception{for(var entry:java.util.Map.of(ErrorCode.DUPLICATE_USERNAME,"username",ErrorCode.DUPLICATE_EMAIL,"email").entrySet()){doThrow(new ArenaOpsException(entry.getKey())).when(service).available(any(),any());mvc.perform(post("/api/academy/staff/login-availability").contentType("application/json").content("{\"username\":\"coach\",\"email\":\"coach@example.test\"}")).andExpect(status().isConflict()).andExpect(jsonPath("$.errorCode").value(entry.getKey().name())).andExpect(jsonPath("$.description").value(entry.getKey().getDescription())).andExpect(jsonPath("$.fieldErrors."+entry.getValue()).value(entry.getKey().getDescription())).andExpect(jsonPath("$.correlationId").isString()).andExpect(jsonPath("$.subject").doesNotExist());}}
 @Test void invalidFormatsAndMissingRequiredFieldsAreRejectedBeforeProvisioning()throws Exception{for(String body:java.util.List.of("{}","{\"username\":\"bad username\",\"email\":\"coach@example.test\"}","{\"username\":\"coach\",\"email\":\"not-email\"}")){mvc.perform(post("/api/academy/staff/login-availability").contentType("application/json").content(body)).andExpect(status().isBadRequest()).andExpect(jsonPath("$.errorCode").value("VALIDATION_FAILED"));}mvc.perform(post("/api/academy/staff/registration").contentType("application/json").content("{}")).andExpect(status().isBadRequest());verifyNoInteractions(service);}
 @Test void unauthenticatedAvailabilityDoesNotExposeAccountData()throws Exception{jwt=null;doThrow(new ArenaOpsException(ErrorCode.ACCESS_DENIED)).when(service).available(isNull(),any());mvc.perform(post("/api/academy/staff/login-availability").contentType("application/json").content("{\"username\":\"coach\",\"email\":\"coach@example.test\"}")).andExpect(status().isForbidden()).andExpect(jsonPath("$.errorCode").value("ACCESS_DENIED")).andExpect(jsonPath("$.available").doesNotExist());}
}
